function wuaBoostCandidate(candidate, globalBoost, overrides){
  const rows=campaignTrail_temp.candidate_state_multiplier_json || [];
  Object.keys(WUA_STATE).forEach(abbr=>{
    const state=WUA_STATE[abbr];
    const boost=Object.prototype.hasOwnProperty.call(overrides,abbr)?overrides[abbr]:globalBoost;
    let row=rows.find(r=>Number(r.fields.candidate)===candidate && Number(r.fields.state)===state);
    if(!row){
      row={model:'campaign_trail.candidate_state_multiplier',pk:9900000+candidate*100+state,
        fields:{candidate,state,state_multiplier:1}};
      rows.push(row);
    }
    row.fields.state_multiplier=Number(row.fields.state_multiplier||1)+boost;
  });
}
