function wuaOppositionHtml(){
  const unlocked=Boolean(typeof WUA!=="undefined" && WUA.oppositionUnlocked);
  if(!unlocked){
    return `<div style="padding:10px 14px;max-width:370px;margin:auto;">
      <h2 style="text-align:center;margin:0 0 10px;">The Opposition</h2>
      <img src="${WUA_OPPOSITION_PLACEHOLDER.photo}" style="display:block;max-width:285px;width:84%;max-height:220px;object-fit:contain;margin:4px auto 10px;" alt="">
      <h3 style="text-align:center;font-size:17px;margin:7px 0 5px;">Republican Ticket Undecided</h3>
      <p style="text-align:center;font-weight:700;font-style:italic;margin:5px auto 0;max-width:320px;">${WUA_OPPOSITION_PLACEHOLDER.summary}</p>
    </div>`;
  }
  const o=WUA.opponent || "Daniels";
  const asset=WUA_OPPOSITION_ASSETS[o] || WUA_OPPOSITION_ASSETS.Daniels;
  const t=WUA_TICKETS[o] || WUA_TICKETS.Daniels;
  return `<div style="padding:10px 14px;max-width:370px;margin:auto;">
    <h2 style="text-align:center;margin:0 0 8px;">The Opposition</h2>
    <img src="${asset.logo}" style="display:block;max-width:285px;width:84%;max-height:220px;object-fit:contain;margin:0 auto 8px;" alt="">
    <img src="${asset.photo}" style="display:block;max-width:285px;width:84%;max-height:220px;object-fit:contain;margin:0 auto 8px;" alt="">
    <h3 style="text-align:center;font-size:17px;margin:7px 0 5px;">${t.first} ${t.last} / ${t.vp}</h3>
    <p style="text-align:center;font-weight:700;font-style:italic;margin:5px auto 0;max-width:320px;">${asset.summary}</p>
  </div>`;
}
function wuaOpenOppositionPanel(){
  document.getElementById("wua_opposition_overlay")?.remove();
  const overlay=document.createElement("div");
  overlay.id="wua_opposition_overlay";
  overlay.style.cssText="position:fixed;inset:0;background:rgba(0,0,0,.58);z-index:99999;display:flex;align-items:center;justify-content:center;padding:18px;";
  overlay.innerHTML=`<div style="position:relative;background:#fff;color:#111;border:3px solid #555;max-width:410px;width:min(410px,94vw);max-height:88vh;overflow:auto;box-shadow:0 5px 22px rgba(0,0,0,.55);">
    <button type="button" id="wua_opposition_close" aria-label="Close" style="position:absolute;right:7px;top:5px;border:0;background:transparent;font-size:27px;line-height:1;cursor:pointer;color:#111;z-index:2;">×</button>
    ${wuaOppositionHtml()}
  </div>`;
  overlay.addEventListener("click",e=>{if(e.target===overlay) overlay.remove();});
  overlay.querySelector("#wua_opposition_close")?.addEventListener("click",()=>overlay.remove());
  document.body.appendChild(overlay);
}

